mapper.select:
select




        and l.xingming like concat('%', #{laorenXingming}, '%')


        and fz.zhangdan_yuefen = #{zhangdanYuefen}


        and  = #{zhuangtai}


order by fz.zhangdan_yuefen desc, fz.id desc

mapper.insert:
insert into feiyong_zhangdan (
    laoren_id, zhangdan_yuefen, chuangwei_fei, huli_fei,
    yaopin_fei, qita_fei, zongjine, zhuangtai, beizhu
) values (
    #{laorenId}, #{zhangdanYuefen}, #{chuangweiFei}, #{huliFei},
    #{yaopinFei}, #{qitaFei}, #{zongjine}, #{zhuangtai}, #{beizhu}
)

mapper.update:
update feiyong_zhangdan
set zhuangtai = '已取消'
where id = #{id}

mapper.select:
select coalesce(sum(jiaofei_jine), 0)
from jiaofei_jilu
where zhangdan_id = #{zhangdanId}

select jf.id, jf.zhangdan_id as zhangdanId, jf.laoren_id as laorenId, l.xingming as laorenXingming, fz.zhangdan_yuefen as zhangdanYuefen, jf.jiaofei_jine as jiaofeiJine, jf.jiaofei_fangshi as jiaofeiFangshi, jf.jiaofei_shijian as jiaofeiShijian, jf.caozuoren_id as caozuorenId, y.xingming as caozuorenXingming, jf.beizhu from jiaofei_jilu jf join feiyong_zhangdan fz on jf.zhangdan_id = fz.id join laoren_xinxi l on jf.laoren_id = l.id left join xitong_yonghu y on jf.caozuoren_id = y.id
and jf.zhangdan_id = #{zhangdanId}
and l.xingming like concat('%', #{laorenXingming}, '%')
and fz.zhangdan_yuefen = #{zhangdanYuefen}
order by jf.jiaofei_shijian desc, jf.id desc

select id, zhangdan_id as zhangdanId, laoren_id as laorenId, jiaofei_jine as jiaofeiJine
from jiaofei_jilu
where id = #{id}

mapper.insert:
insert into jiaofei_jilu (
    zhangdan_id, laoren_id, jiaofei_jine, jiaofei_fangshi,
    jiaofei_shijian, caozuoren_id, beizhu
) values (
    #{zhangdanId}, #{laorenId}, #{jiaofeiJine}, #{jiaofeiFangshi},
    coalesce(#{jiaofeiShijian}, now()), #{caozuorenId}, #{beizhu}
)

mapper.update:
update feiyong_zhangdan
set zhuangtai = #{zhuangtai}
where id = #{id}
  and zhuangtai != '已取消'
